package com.eventhub.controller;import com.eventhub.dto.TicketResponse;import com.eventhub.service.TicketService;import lombok.RequiredArgsConstructor;import org.springframework.http.ResponseEntity;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/tickets") @RequiredArgsConstructor public class TicketController{private final TicketService service;@GetMapping("/{id}") @PreAuthorize("isAuthenticated()") public ResponseEntity<TicketResponse> get(org.springframework.security.core.Authentication a,@PathVariable String id){return ResponseEntity.ok(service.get(a.getName(),id));}}
